  $mtjson${"slug": "medical-terminology", "title": "Medical Terminology", "description": "This course teaches students to decode, pronounce, spell, use, document, and translate medical vocabulary across body systems and clinical settings. Students learn word parts, abbreviations, anatomy language, body-system terms, pathology, diagnostics, procedures, pharmacology, EHR documentation, coding awareness, health literacy, and interprofessional communication.", "topics": [{"id": "fe588133-f818-4b1a-8e3e-4c60965d916d", "type": "topic", "title": "Medical language foundations: word parts, meaning, and learning strategy", "description": "Build a durable method for decoding and constructing clinical terms rather than memorizing isolated words.", "children": [{"id": "a3a35841-840b-4b5a-9318-c6c7f67e96d2", "type": "subtopic", "title": "Word-building logic", "description": "Students learn the reusable structure of medical terms so unfamiliar words become solvable puzzles.", "children": [{"id": "e35d6a9a-468d-403b-848f-897f0700a025", "type": "concept", "title": "Roots, combining forms, prefixes, and suffixes"}, {"id": "97fad549-63fa-4413-8acd-63f7ab69a251", "type": "concept", "title": "Combining vowels and word construction"}, {"id": "e7ba1906-f679-41e1-9902-b7fbb985dfa5", "type": "concept", "title": "Singular, plural, adjective, noun, and procedure forms"}]}, {"id": "740a641f-7570-41a7-a2ff-56e358bf367b", "type": "subtopic", "title": "Meaning from context", "description": "This subtopic teaches students to interpret terms using body system, clinical setting, and surrounding words.", "children": [{"id": "bbc68428-612f-42e0-a1c8-30332b74e54a", "type": "concept", "title": "Symptom, diagnosis, procedure, test, and medication contexts"}, {"id": "7c24eb3d-bba3-4688-8ccc-f3dae9a85db9", "type": "concept", "title": "Literal meaning versus clinical meaning"}, {"id": "72146c79-7bc9-410b-84ed-4304a8f91b49", "type": "concept", "title": "Eponyms, acronyms, and common exceptions"}]}, {"id": "3e76fc5c-4dee-47f0-94c9-2c8b5602c5b1", "type": "subtopic", "title": "Study system and retrieval practice", "description": "Students learn how to retain vocabulary long-term.", "children": [{"id": "0ea51645-1d48-4f20-80de-d976496efc10", "type": "concept", "title": "Flashcards and spaced repetition"}, {"id": "ade35457-b2bc-49e3-91cf-de1527f4ec96", "type": "concept", "title": "Word-part notebooks and body-system maps"}, {"id": "c990a3b2-f6f2-41b8-ad64-5259d3281d9c", "type": "concept", "title": "Case-based decoding and pronunciation practice"}]}]}, {"id": "8414e044-fd42-4889-ba36-9604d2c7f99b", "type": "topic", "title": "Pronunciation, spelling, pluralization, abbreviations, and patient-safety language", "description": "Use medical terms clearly and safely, with attention to sound-alike words, spelling, and abbreviation risk.", "children": [{"id": "ca4cbdd4-9c7b-43bf-bb28-431e4a5c8f90", "type": "subtopic", "title": "Pronunciation and spelling accuracy", "description": "Students learn why small language errors can create clinical confusion.", "children": [{"id": "505c49de-3d11-447f-8df8-41df76165ed8", "type": "concept", "title": "Syllable stress and phonetic practice"}, {"id": "eb088dc9-24ac-48bb-bc4e-600b89595931", "type": "concept", "title": "Look-alike and sound-alike terms"}, {"id": "e6fa24a7-425b-4e80-81cb-af0f979e0a64", "type": "concept", "title": "Common spelling traps and proofreading"}]}, {"id": "b3c61d11-3d8e-4e95-8b6d-74125c501910", "type": "subtopic", "title": "Pluralization and grammar", "description": "This subtopic supports precise charting and professional communication.", "children": [{"id": "5b8abc60-1cb8-47af-bd19-e64672bc8a8e", "type": "concept", "title": "Latin and Greek plural patterns"}, {"id": "3f299891-e8a2-4054-b267-f308fc860f50", "type": "concept", "title": "Adjective and noun agreement"}, {"id": "38fa201c-512e-4643-9f0d-dc68816f1b3f", "type": "concept", "title": "Common singular/plural clinical forms"}]}, {"id": "465c287f-f62c-41ed-9f64-5160385b3503", "type": "subtopic", "title": "Abbreviations and safety", "description": "Students learn to use abbreviations cautiously and recognize when plain language is safer.", "children": [{"id": "0b4b37c7-80be-47d2-8ec0-dfc712172806", "type": "concept", "title": "Common approved abbreviations"}, {"id": "d60bea04-d1b2-452d-9181-bfa5cf4faa13", "type": "concept", "title": "Ambiguous abbreviations and do-not-use thinking"}, {"id": "c3a5295e-77ea-4da4-8d50-805ae337a883", "type": "concept", "title": "Clarification, read-back, and closed-loop communication"}]}]}, {"id": "03048aa3-8a2e-4ed4-84cb-753b3cdfddae", "type": "topic", "title": "Body organization: planes, directions, cavities, regions, and clinical orientation", "description": "Describe anatomy and location precisely using the shared language of clinical practice.", "children": [{"id": "28748121-53a2-4c07-9c2b-2b3241f9cfed", "type": "subtopic", "title": "Anatomic position and direction", "description": "Students learn the coordinate system used to describe body location reliably.", "children": [{"id": "930401a9-4278-4395-9774-618a3ef28b83", "type": "concept", "title": "Anterior/posterior, medial/lateral, proximal/distal"}, {"id": "81ce37c4-1d7f-417b-b67b-787958ff3a13", "type": "concept", "title": "Superior/inferior, superficial/deep"}, {"id": "14cb3b61-03aa-4fa4-bed8-058a31890e59", "type": "concept", "title": "Ipsilateral/contralateral and bilateral/unilateral"}]}, {"id": "0cd47f05-9d6a-458b-971b-b503b086400e", "type": "subtopic", "title": "Planes, sections, and cavities", "description": "This subtopic prepares students for imaging, procedures, and anatomy descriptions.", "children": [{"id": "ef26a4b4-64cb-46f7-b26a-7c30c64d3e03", "type": "concept", "title": "Sagittal, coronal/frontal, transverse/axial"}, {"id": "73cf1e50-da17-4ed7-a68f-bdf89ea9f46d", "type": "concept", "title": "Dorsal, ventral, thoracic, abdominal, pelvic cavities"}, {"id": "61d0f30b-31df-4848-af62-01074c522d32", "type": "concept", "title": "Serous